(r, big) => {
    const n = big ? 100 : r.int(2, 6);
    for (;;) {
      const g = r.matrix(n, n, 0, 1);
      const lab = g.map(row => row.map(() => -1)), sizes = [];
      for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
        if (g[i][j] !== 1 || lab[i][j] !== -1) continue;
        const id = sizes.length, st = [[i, j]];
        lab[i][j] = id; let size = 0;
        while (st.length) {
          const [a, b] = st.pop(); size++;
          for (const [x, y] of [[a + 1, b], [a - 1, b], [a, b + 1], [a, b - 1]])
            if (x >= 0 && y >= 0 && x < n && y < n && g[x][y] === 1 && lab[x][y] === -1) { lab[x][y] = id; st.push([x, y]); }
        }
        sizes.push(size);
      }
      if (sizes.length < 2) continue;
      const order = sizes.map((s, k) => k).sort((p, q) => sizes[q] - sizes[p]);
      const keep = big ? [order[0], order[1]] : r.shuffle(order).slice(0, 2);
      for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) if (g[i][j] === 1 && !keep.includes(lab[i][j])) g[i][j] = 0;
      return [g];
    }
  }

