function joinIslands(grid: number[][]): number {
  const n = grid.length, mine: number[][] = [], other: number[][] = [];
  const seen = grid.map(row => row.map(() => false));
  let si = -1, sj = -1;
  for (let i = 0; i < n && si < 0; i++) for (let j = 0; j < n; j++) if (grid[i][j] === 1) { si = i; sj = j; break; }
  const stack = [[si, sj]];
  seen[si][sj] = true;
  while (stack.length) {
    const [i, j] = stack.pop()!;
    mine.push([i, j]);
    for (const [x, y] of [[i + 1, j], [i - 1, j], [i, j + 1], [i, j - 1]])
      if (x >= 0 && y >= 0 && x < n && y < n && grid[x][y] === 1 && !seen[x][y]) { seen[x][y] = true; stack.push([x, y]); }
  }
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) if (grid[i][j] === 1 && !seen[i][j]) other.push([i, j]);
  let best = Infinity;
  for (const [a, b] of mine) for (const [c, d] of other) best = Math.min(best, Math.abs(a - c) + Math.abs(b - d) - 1);
  return best;
}

