function joinIslands(grid: number[][]): number {
  const n = grid.length;
  const g = grid.map(row => row.slice());
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let queue: number[][] = [];
  // flood fill the first island, marking it 2 and seeding the BFS
  outer: for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    if (g[i][j] !== 1) continue;
    const stack = [[i, j]];
    g[i][j] = 2;
    while (stack.length) {
      const [a, b] = stack.pop()!;
      queue.push([a, b]);
      for (const [dx, dy] of dirs) {
        const x = a + dx, y = b + dy;
        if (x >= 0 && y >= 0 && x < n && y < n && g[x][y] === 1) { g[x][y] = 2; stack.push([x, y]); }
      }
    }
    break outer;
  }
  for (let steps = 0; queue.length; steps++) {
    const next: number[][] = [];
    for (const [a, b] of queue)
      for (const [dx, dy] of dirs) {
        const x = a + dx, y = b + dy;
        if (x < 0 || y < 0 || x >= n || y >= n || g[x][y] === 2) continue;
        if (g[x][y] === 1) return steps; // reached the other island
        g[x][y] = 2;
        next.push([x, y]);
      }
    queue = next;
  }
  return -1;
}

